// legacyProgressRow is one playback_progress row as the pre-accounts code
// wrote it (the item_id-only PK table this change's rebuild replaces).
type legacyProgressRow struct {
	itemID          string
	positionSeconds int64
	updatedAt       string
}

// legacyWatchedRow is one watched_items row as the pre-accounts code wrote
// it. Nulls are explicit: series_relative_path is NULL for film/tv items and
// applied_at stays NULL until the learning pass stamps it — the rebuild must
// carry both states through verbatim.
type legacyWatchedRow struct {
	itemID             string
	libraryID          int64
	seriesRelativePath sql.NullString
	completedAt        string
	appliedAt          sql.NullString
}

// seedLegacyLedgers rebuilds both ledger tables into their PRE-accounts
// shapes on a store Opened with the current schema (fresh DBs are born with
// the user-scoped shape, so the drop/recreate simulates the older database)
// and seeds the given rows — the database state the rebuild must find on the
// next Open.
func seedLegacyLedgers(t *testing.T, ctx context.Context, s *Store,
	progress []legacyProgressRow, watched []legacyWatchedRow) {
	t.Helper()
	for _, ddl := range []string{
		`DROP TABLE playback_progress`,
		`DROP TABLE watched_items`,
		`CREATE TABLE playback_progress (
  item_id          TEXT PRIMARY KEY,
  position_seconds INTEGER NOT NULL CHECK (position_seconds >= 0),
  updated_at       TEXT NOT NULL
)`,
		`CREATE TABLE watched_items (
  item_id              TEXT PRIMARY KEY,
  library_id           INTEGER NOT NULL,
  series_relative_path TEXT,
  completed_at         TEXT NOT NULL,
  applied_at           TEXT
)`,
	} {
		if _, err := s.db.ExecContext(ctx, ddl); err != nil {
			t.Fatalf("seed legacy ledger shape: %v (%s)", err, ddl)
		}
	}
	for _, r := range progress {
		if _, err := s.db.ExecContext(ctx, `
INSERT INTO playback_progress (item_id, position_seconds, updated_at)
VALUES (?, ?, ?)`, r.itemID, r.positionSeconds, r.updatedAt); err != nil {
			t.Fatalf("seed legacy progress row %s: %v", r.itemID, err)
		}
	}
	for _, r := range watched {
		if _, err := s.db.ExecContext(ctx, `
INSERT INTO watched_items (item_id, library_id, series_relative_path, completed_at, applied_at)
VALUES (?, ?, ?, ?, ?)`,
			r.itemID, r.libraryID, r.seriesRelativePath, r.completedAt, r.appliedAt); err != nil {
			t.Fatalf("seed legacy watched row %s: %v", r.itemID, err)
		}
	}
}

// TestLedgerRebuildPreservesRows covers the rebuild's migration contract
// (accounts 2.3): a database carrying N legacy ledger rows, when Opened,
// comes back with every row readable in the user_id=0 slot with positions,
// stamps, and NULLs intact — zero row loss — under the new composite PK;
// the pre-accounts write paths still behave on the rebuilt tables (the
// PutProgress upsert overwrites the legacy row in place, InsertWatched
// keeps a rewatch a no-op); and a further Open is a no-op.
func TestLedgerRebuildPreservesRows(t *testing.T) {
	ctx := context.Background()
	dsn := filepath.Join(t.TempDir(), "ledger-legacy.db")

	legacyProgress := []legacyProgressRow{
		{itemID: "itm_a", positionSeconds: 120, updatedAt: "2026-10-01T10:00:00Z"},
		{itemID: "itm_b", positionSeconds: 0, updatedAt: "2026-10-02T11:30:00Z"},
		{itemID: "itm_c", positionSeconds: 3600, updatedAt: "2026-10-03T12:45:30.5Z"},
	}
	legacyWatched := []legacyWatchedRow{
		{itemID: "itm_a", libraryID: 1,
			completedAt: "2026-10-01T10:05:00Z",
			appliedAt:   sql.NullString{String: "2026-10-02T00:00:00Z", Valid: true}},
		{itemID: "itm_b", libraryID: 2,
			seriesRelativePath: sql.NullString{String: "serials/show", Valid: true},
			completedAt:        "2026-10-02T11:35:00Z"},
		{itemID: "itm_d", libraryID: 1,
			completedAt: "2026-10-03T09:00:00Z"},
	}

	s := reopenStore(t, dsn)
	seedLegacyLedgers(t, ctx, s, legacyProgress, legacyWatched)
	if err := s.Close(); err != nil {
		t.Fatalf("Close pre-rebuild: %v", err)
	}

	// Boot 2 — Open runs the rebuild: every legacy row lands in slot 0.
	s = reopenStore(t, dsn)
	defer s.Close()

	rows, err := s.db.QueryContext(ctx, `
SELECT user_id, item_id, position_seconds, updated_at
FROM playback_progress ORDER BY item_id`)
	if err != nil {
		t.Fatalf("read rebuilt progress: %v", err)
	}
	defer rows.Close()
	var gotProgress []legacyProgressRow
	for rows.Next() {
		var (
			userID int64
			r      legacyProgressRow
		)
		if err := rows.Scan(&userID, &r.itemID, &r.positionSeconds, &r.updatedAt); err != nil {
			t.Fatalf("scan rebuilt progress: %v", err)
		}
		if userID != 0 {
			t.Errorf("progress row %s user_id = %d, want 0 (the legacy slot)", r.itemID, userID)
		}
		gotProgress = append(gotProgress, r)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("iterate rebuilt progress: %v", err)
	}
	if len(gotProgress) != len(legacyProgress) {
		t.Fatalf("rebuilt progress rows = %d, want %d (zero row loss)", len(gotProgress), len(legacyProgress))
	}
	for i, got := range gotProgress {
		if got != legacyProgress[i] { // ORDER BY item_id matches the seeded order
			t.Errorf("progress row %d = %+v, want the verbatim legacy row %+v", i, got, legacyProgress[i])
		}
	}

	rows2, err := s.db.QueryContext(ctx, `
SELECT user_id, item_id, library_id, series_relative_path, completed_at, applied_at
FROM watched_items ORDER BY item_id`)
	if err != nil {
		t.Fatalf("read rebuilt watched: %v", err)
	}
	defer rows2.Close()
	type watchedRow struct {
		userID int64
		legacyWatchedRow
	}
	var gotWatched []watchedRow
	for rows2.Next() {
		var w watchedRow
		if err := rows2.Scan(&w.userID, &w.itemID, &w.libraryID,
			&w.seriesRelativePath, &w.completedAt, &w.appliedAt); err != nil {
			t.Fatalf("scan rebuilt watched: %v", err)
		}
		gotWatched = append(gotWatched, w)
	}
	if err := rows2.Err(); err != nil {
		t.Fatalf("iterate rebuilt watched: %v", err)
	}
	if len(gotWatched) != len(legacyWatched) {
		t.Fatalf("rebuilt watched rows = %d, want %d (zero row loss)", len(gotWatched), len(legacyWatched))
	}
	for i, got := range gotWatched {
		want := legacyWatched[i] // ORDER BY item_id matches the seeded order
		if got.userID != 0 {
			t.Errorf("watched row %s user_id = %d, want 0 (the legacy slot)", got.itemID, got.userID)
		}
		if got.itemID != want.itemID || got.libraryID != want.libraryID ||
			got.seriesRelativePath != want.seriesRelativePath ||
			got.completedAt != want.completedAt || got.appliedAt != want.appliedAt {
			t.Errorf("watched row %d = %+v, want the verbatim legacy row %+v", i, got.legacyWatchedRow, want)
		}
	}

	// The rebuilt PK is the composite: user_id first, item_id second.
	for _, table := range []string{"playback_progress", "watched_items"} {
		cols := tableColumns(t, ctx, s.db, table)
		if cols["user_id"].pk != 1 || cols["item_id"].pk != 2 {
			t.Errorf("%s PK = user_id→%d item_id→%d, want user_id→1 item_id→2",
				table, cols["user_id"].pk, cols["item_id"].pk)
		}
	}

	// The pre-accounts write paths still behave against the rebuilt tables.
	// PutProgress needs the item to exist (its existence gate); the others
	// have no gate.
	if err := s.PutItem(ctx, Item{
		ID: "itm_a", ModuleID: "tv", LibraryID: 1, FileID: "rebuild",
		RelativePath: "itm_a.mkv", MediaType: "tv",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("seed item: %v", err)
	}
	if _, err := s.PutProgress(ctx, "itm_a", 240, access.System()); err != nil {
		t.Fatalf("PutProgress on rebuilt table: %v", err)
	}
	if n := tableCount(t, ctx, s, "SELECT COUNT(*) FROM playback_progress"); n != len(legacyProgress) {
		t.Fatalf("progress rows after PutProgress = %d, want %d (upsert overwrote, no duplicate)", n, len(legacyProgress))
	}
	got, err := s.GetProgress(ctx, "itm_a", access.System())
	if err != nil {
		t.Fatalf("GetProgress on rebuilt table: %v", err)
	}
	if got.PositionSeconds != 240 {
		t.Fatalf("position after upsert = %d, want 240", got.PositionSeconds)
	}
	if err := s.InsertWatched(ctx, "itm_a", 1, "", time.Date(2026, 11, 1, 0, 0, 0, 0, time.UTC), access.System()); err != nil {
		t.Fatalf("InsertWatched on rebuilt table: %v", err)
	}
	if n := tableCount(t, ctx, s, "SELECT COUNT(*) FROM watched_items"); n != len(legacyWatched) {
		t.Fatalf("watched rows after rewatch insert = %d, want %d (no-op keeps the first stamp)", n, len(legacyWatched))
	}
	var stamp string
	if err := s.db.QueryRowContext(ctx,
		"SELECT completed_at FROM watched_items WHERE item_id = 'itm_a'").Scan(&stamp); err != nil {
		t.Fatalf("read kept stamp: %v", err)
	}
	if stamp != "2026-10-01T10:05:00Z" {
		t.Fatalf("completed_at after rewatch = %q, want the FIRST stamp kept", stamp)
	}

	// Rerun no-op: another Open over the rebuilt database changes nothing.
	if err := s.Close(); err != nil {
		t.Fatalf("Close rebuilt: %v", err)
	}
	s = reopenStore(t, dsn)
	defer s.Close()
	if n := tableCount(t, ctx, s, "SELECT COUNT(*) FROM playback_progress"); n != len(legacyProgress) {
		t.Fatalf("progress rows after rerun = %d, want %d", n, len(legacyProgress))
	}
	if n := tableCount(t, ctx, s, "SELECT COUNT(*) FROM watched_items"); n != len(legacyWatched) {
		t.Fatalf("watched rows after rerun = %d, want %d", n, len(legacyWatched))
	}
}

// TestLedgerRebuildIdempotent pins the two green paths' shapes (accounts
// 2.3): a FRESH database is born user-scoped (the composite PK, the NOT NULL
// DEFAULT 0 slot column, the two ledger indexes present) and a RERUN of Open
// over an existing database is a true no-op (stored DDL byte-identical, rows
// untouched).
func TestLedgerRebuildIdempotent(t *testing.T) {
	ctx := context.Background()
	dsn := filepath.Join(t.TempDir(), "ledger-fresh.db")

	// Fresh-DB shape.
	s := reopenStore(t, dsn)
	for _, table := range []string{"playback_progress", "watched_items"} {
		cols := tableColumns(t, ctx, s.db, table)
		if len(cols) == 0 {
			t.Fatalf("%s: table missing on fresh DB", table)
		}
		userID, ok := cols["user_id"]
		if !ok {
			t.Fatalf("%s: user_id column missing on fresh DB", table)
		}
		if userID.ctype != "INTEGER" || !userID.notnull ||
			userID.dflt.String != "0" || !userID.dflt.Valid {
			t.Errorf("%s.user_id = %q notnull=%v dflt=%v, want INTEGER NOT NULL DEFAULT 0",
				table, userID.ctype, userID.notnull, userID.dflt)
		}
		if userID.pk != 1 || cols["item_id"].pk != 2 {
			t.Errorf("%s PK = user_id→%d item_id→%d, want user_id→1 item_id→2",
				table, userID.pk, cols["item_id"].pk)
		}
	}
	for _, index := range []string{"watched_items_completed_at", "watched_items_applied_at"} {
		var name string
		err := s.db.QueryRowContext(ctx,
			`SELECT name FROM sqlite_master WHERE type = 'index' AND name = ?`, index).Scan(&name)
		if err != nil {
			t.Errorf("fresh DB missing index %s: %v", index, err)
		}
	}

	// Seed rows the rerun must leave untouched, then snapshot the stored DDL.
	if _, err := s.db.ExecContext(ctx, `
INSERT INTO playback_progress (user_id, item_id, position_seconds, updated_at)
VALUES (0, 'itm_fresh', 60, '2026-11-01T00:00:00Z')`); err != nil {
		t.Fatalf("seed fresh progress row: %v", err)
	}
	if err := s.InsertWatched(ctx, "itm_fresh", 1, "", time.Date(2026, 11, 1, 1, 0, 0, 0, time.UTC), access.System()); err != nil {
		t.Fatalf("seed fresh watched row: %v", err)
	}
	ddlBefore := map[string]string{
		"playback_progress": tableDDL(t, ctx, s.db, "playback_progress"),
		"watched_items":     tableDDL(t, ctx, s.db, "watched_items"),
	}
	if err := s.Close(); err != nil {
		t.Fatalf("Close first boot: %v", err)
	}

	// Rerun: the PK guard skips the rebuild — the stored DDL (renamed in
	// place by a rebuild; recreated from scratch by one) stays identical and
	// the rows survive.
	s = reopenStore(t, dsn)
	defer s.Close()
	for table, before := range ddlBefore {
		if after := tableDDL(t, ctx, s.db, table); after != before {
			t.Errorf("%s DDL changed across the rerun (rebuild ran):\nbefore: %s\nafter:  %s", table, before, after)
		}
	}
	if n := tableCount(t, ctx, s, "SELECT COUNT(*) FROM playback_progress"); n != 1 {
		t.Errorf("progress rows after rerun = %d, want 1", n)
	}
	if n := tableCount(t, ctx, s, "SELECT COUNT(*) FROM watched_items"); n != 1 {
		t.Errorf("watched rows after rerun = %d, want 1", n)
	}
}
